contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner) public payable {
        require(newOwner != address(0));

        address originalOwner = c.owner();
        require(msg.sender != originalOwner);

        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted && c.owner() == originalOwner);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner) public payable {
        require(newOwner != address(0), "newOwner must be non-zero");

        address beforeOwner = c.owner();

        bool ownedReverted;
        try c.owned() {
            ownedReverted = false;
        } catch {
            ownedReverted = true;
        }

        bool transferReverted;
        try c.transferOwnership(newOwner) {
            transferReverted = false;
        } catch {
            transferReverted = true;
        }

        address afterOwner = c.owner();

        assert(ownedReverted && transferReverted && beforeOwner == address(0) && afterOwner == beforeOwner);
    }

    receive() external payable {}
}

